CREATE TABLE IF NOT EXISTS ai_usage_quota ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "user_id" BIGINT NOT NULL, "date" DATE NOT NULL, "gps_enhanced_requests" INTEGER NOT NULL DEFAULT 0, "pincode_requests" INTEGER NOT NULL DEFAULT 0, "last_reset" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "quota_limit" INTEGER NOT NULL DEFAULT 20);

