CREATE TABLE IF NOT EXISTS buyer_interests ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "listing_id" BIGINT NOT NULL, "buyer_name" VARCHAR(255) NOT NULL, "buyer_phone" VARCHAR(255) NOT NULL, "buyer_email" VARCHAR(255) NULL, "buyer_type" VARCHAR(255) NOT NULL, "interested_quantity" INTEGER NOT NULL, "message" TEXT NULL, "status" VARCHAR(255) DEFAULT 'pending', "delivery_latitude" DECIMAL(10,8) NULL, "delivery_longitude" DECIMAL(11,8) NULL, "delivery_pincode" VARCHAR(10) NULL, "delivery_state" VARCHAR(100) NULL, "delivery_district" VARCHAR(100) NULL, "delivery_village" VARCHAR(100) NULL, "delivery_address_line" VARCHAR(255) NULL);

CREATE TABLE IF NOT EXISTS crops ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "farm_plot_id" BIGINT NOT NULL, "strategy_id" BIGINT NULL, "crop_name" VARCHAR(255) NOT NULL, "crop_variety" VARCHAR(255) NULL, "season" VARCHAR(255) NOT NULL, "planting_date" DATE NOT NULL, "expected_harvest_date" DATE NOT NULL, "area" DECIMAL(10,2) NOT NULL, "expected_yield" DECIMAL(12,2) NULL, "expected_profit" DECIMAL(12,2) NULL, "actual_yield" DECIMAL(12,2) NULL, "actual_profit" DECIMAL(12,2) NULL, "status" VARCHAR(255) DEFAULT 'planned', "parent_crop_id" BIGINT NULL, "crop_role" VARCHAR(20) DEFAULT 'main');

