CREATE TABLE IF NOT EXISTS crop_profitability ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "crop_type" VARCHAR(100) NOT NULL, "variety" VARCHAR(200) NULL, "state" VARCHAR(100) NOT NULL, "district" VARCHAR(100) NULL, "year" INTEGER NOT NULL, "season" VARCHAR(50) NULL, "avg_profit_per_acre" DECIMAL(10,2) NOT NULL, "min_profit_per_acre" DECIMAL(10,2) NULL, "max_profit_per_acre" DECIMAL(10,2) NULL, "seed_cost" DECIMAL(10,2) NULL, "fertilizer_cost" DECIMAL(10,2) NULL, "pesticide_cost" DECIMAL(10,2) NULL, "labor_cost" DECIMAL(10,2) NULL, "irrigation_cost" DECIMAL(10,2) NULL, "equipment_cost" DECIMAL(10,2) NULL, "other_costs" DECIMAL(10,2) NULL, "total_investment_cost" DECIMAL(10,2) NULL, "avg_revenue_per_acre" DECIMAL(10,2) NULL, "roi_percentage" DECIMAL(5,2) NULL, "break_even_yield" DECIMAL(10,2) NULL, "profit_margin" DECIMAL(5,2) NULL, "risk_level" VARCHAR(20) NULL, "price_risk_score" DECIMAL(3,2) NULL, "yield_risk_score" DECIMAL(3,2) NULL, "market_demand" VARCHAR(20) NULL, "competition_level" VARCHAR(20) NULL, "data_source" VARCHAR(100) NULL, "sample_size" INTEGER NULL);

