CREATE TABLE IF NOT EXISTS price_predictions ("id" BIGSERIAL PRIMARY KEY, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, "enable" SMALLINT NOT NULL DEFAULT 1, "item_type" VARCHAR(50) NOT NULL, "item_name" VARCHAR(255) NOT NULL, "variety" VARCHAR(255) NULL, "state" VARCHAR(100) NOT NULL, "district" VARCHAR(100) NULL, "prediction_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "target_date" DATE NOT NULL, "predicted_price" DECIMAL(10,2) NOT NULL, "confidence_score" DECIMAL(3,2) NOT NULL, "price_range_min" DECIMAL(10,2) NULL, "price_range_max" DECIMAL(10,2) NULL, "trend" VARCHAR(20) NULL, "demand_forecast" VARCHAR(20) NULL, "supply_forecast" VARCHAR(20) NULL, "season" VARCHAR(50) NULL, "model_version" VARCHAR(50) NULL, "factors" TEXT NULL);

